#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "eval.h"

static char *dupstr(const char *s) { size_t n; char *p; if (!s) return NULL; n=strlen(s); p=malloc(n+1); if (p) memcpy(p,s,n+1); return p; }

struct JCMEnv *jcm_env_new(struct JCMEnv *parent) { struct JCMEnv *e=malloc(sizeof *e); if (!e) return NULL; e->bindings=NULL; e->parent=parent; return e; }
void jcm_env_free(struct JCMEnv *e) { struct JCMBinding *b,*n; if (!e) return; for (b=e->bindings;b;b=n) { n=b->next; free(b->name); free(b); } free(e); }
int jcm_env_define(struct JCMEnv *e,const char *name,struct JCMValue v) { struct JCMBinding *b; if (!e||!name) return 0; b=malloc(sizeof *b); if (!b) return 0; b->name=dupstr(name); if (!b->name) { free(b); return 0; } b->value=v; b->next=e->bindings; e->bindings=b; return 1; }
int jcm_env_set(struct JCMEnv *e,const char *name,struct JCMValue v) { struct JCMEnv *p; struct JCMBinding *b; for(p=e;p;p=p->parent) for(b=p->bindings;b;b=b->next) if(!strcmp(b->name,name)){b->value=v;return 1;} return 0; }
int jcm_env_get(struct JCMEnv *e,const char *name,struct JCMValue *v) { struct JCMEnv *p; struct JCMBinding *b; if(!e||!name||!v)return 0; for(p=e;p;p=p->parent) for(b=p->bindings;b;b=b->next) if(!strcmp(b->name,name)){*v=b->value;return 1;} return 0; }
struct JCMValue jcm_value_number(long n) { struct JCMValue v; v.kind=JCM_VALUE_NUMBER; v.value.number=n; return v; }
struct JCMValue jcm_value_string(const char *s) { struct JCMValue v; v.kind=JCM_VALUE_STRING; v.value.string=dupstr(s); return v; }
struct JCMValue jcm_value_function(struct JCMFunction *f) { struct JCMValue v; v.kind=JCM_VALUE_FUNCTION; v.value.function=f; return v; }
int jcm_runtime_init(struct JCMRuntime *r) { if(!r)return 0; r->global=jcm_env_new(NULL); if(!r->global)return 0; r->memory.cells=NULL; r->memory.next_address=1; return 1; }
void jcm_runtime_free(struct JCMRuntime *r) { struct JCMMemoryCell *c,*n; if(!r)return; jcm_env_free(r->global); r->global=NULL; for(c=r->memory.cells;c;c=n){n=c->next;free(c);} r->memory.cells=NULL; r->memory.next_address=0; }
int jcm_memory_load(struct JCMMemory *m,long a,struct JCMValue *v) { struct JCMMemoryCell *c; if(!m||!v)return 0; for(c=m->cells;c;c=c->next)if(c->address==a){*v=c->value;return 1;}return 0; }
int jcm_memory_store(struct JCMMemory *m,long a,struct JCMValue v) { struct JCMMemoryCell *c; if(!m)return 0; for(c=m->cells;c;c=c->next)if(c->address==a){c->value=v;return 1;} c=malloc(sizeof *c);if(!c)return 0;c->address=a;c->value=v;c->next=m->cells;m->cells=c;return 1; }

static int eval(struct JCMRuntime *,struct JCMEnv *,const struct JCMAst *,struct JCMValue *);
static int number_arg(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,long *n){struct JCMValue v;if(!eval(r,e,a,&v)||v.kind!=JCM_VALUE_NUMBER)return 0;*n=v.value.number;return 1;}
static int call_function(struct JCMRuntime *r,struct JCMValue fv,struct JCMValue arg,struct JCMValue *out){struct JCMFunction *f;const struct JCMAst *l,*p;struct JCMEnv *ce; if(fv.kind!=JCM_VALUE_FUNCTION||(f=fv.value.function)==NULL||(l=f->lambda)==NULL||l->value.list.count!=3)return 0;p=l->value.list.items[1];if(p->kind!=JCM_AST_LIST||p->value.list.count!=1||p->value.list.items[0]->kind!=JCM_AST_SYMBOL)return 0;ce=jcm_env_new(f->env);if(!ce)return 0;if(!jcm_env_define(ce,p->value.list.items[0]->value.symbol,arg)){jcm_env_free(ce);return 0;}return eval(r,ce,l->value.list.items[2],out);}

static int eval_binary(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,enum JCMOp op,struct JCMValue *out){long x,y;if(a->value.list.count!=3||!number_arg(r,e,a->value.list.items[1],&x)||!number_arg(r,e,a->value.list.items[2],&y))return 0;switch(op){case JCM_ADD:*out=jcm_value_number(x+y);return 1;case JCM_SUB:*out=jcm_value_number(x-y);return 1;case JCM_MUL:*out=jcm_value_number(x*y);return 1;case JCM_DIV:if(!y)return 0;*out=jcm_value_number(x/y);return 1;case JCM_MOD:if(!y)return 0;*out=jcm_value_number(x%y);return 1;default:return 0;}}
static int eval_compare(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,enum JCMOp op,struct JCMValue *out){long x,y,z;if(a->value.list.count!=3||!number_arg(r,e,a->value.list.items[1],&x)||!number_arg(r,e,a->value.list.items[2],&y))return 0;switch(op){case JCM_EQ:z=x==y;break;case JCM_LT:z=x<y;break;case JCM_LE:z=x<=y;break;case JCM_GT:z=x>y;break;case JCM_GE:z=x>=y;break;default:return 0;}*out=jcm_value_number(z);return 1;}
static int eval_sum_product(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,int product,struct JCMValue *out){long lo,hi,i,total;struct JCMValue term;struct JCMEnv *loop;const struct JCMAst *name=a->value.list.items[1];if(a->value.list.count!=5||name->kind!=JCM_AST_SYMBOL||!number_arg(r,e,a->value.list.items[2],&lo)||!number_arg(r,e,a->value.list.items[3],&hi))return 0;total=product?1:0;for(i=lo;i<=hi;i++){loop=jcm_env_new(e);if(!loop||!jcm_env_define(loop,name->value.symbol,jcm_value_number(i))||!eval(r,loop,a->value.list.items[4],&term)){jcm_env_free(loop);return 0;}jcm_env_free(loop);if(term.kind!=JCM_VALUE_NUMBER)return 0;if(product)total*=term.value.number;else total+=term.value.number;if(i==hi)break;}*out=jcm_value_number(total);return 1;}
static int eval_integral(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,struct JCMValue *out){struct JCMValue f,lv,rv;long lo,hi,steps,i,x1,x2,y1,y2,total;if(a->value.list.count!=5||!eval(r,e,a->value.list.items[1],&f)||f.kind!=JCM_VALUE_FUNCTION||!number_arg(r,e,a->value.list.items[2],&lo)||!number_arg(r,e,a->value.list.items[3],&hi)||!number_arg(r,e,a->value.list.items[4],&steps)||steps<=0)return 0;total=0;for(i=0;i<steps;i++){x1=lo+(hi-lo)*i/steps;x2=lo+(hi-lo)*(i+1)/steps;if(!call_function(r,f,jcm_value_number(x1),&lv)||!call_function(r,f,jcm_value_number(x2),&rv)||lv.kind!=JCM_VALUE_NUMBER||rv.kind!=JCM_VALUE_NUMBER)return 0;y1=lv.value.number;y2=rv.value.number;total+=(y1+y2)*(x2-x1)/2;}*out=jcm_value_number(total);return 1;}

static int eval(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,struct JCMValue *out){enum JCMOp op;struct JCMValue v,w;long n;const struct JCMAst *name;struct JCMFunction *f;struct JCMEnv *ce;if(!r||!e||!a||!out)return 0;switch(a->kind){case JCM_AST_NUMBER:*out=jcm_value_number((long)a->value.number);return 1;case JCM_AST_STRING:*out=jcm_value_string(a->value.string);return out->value.string!=NULL;case JCM_AST_SYMBOL:return jcm_env_get(e,a->value.symbol,out);case JCM_AST_PROGRAM:return jcm_eval_program(r,a,out);case JCM_AST_CORE:return 0;case JCM_AST_LIST:break;}if(!a->value.list.count)return 0;if(a->value.list.items[0]->kind!=JCM_AST_CORE)return call_function(r,(eval(r,e,a->value.list.items[0],&v),v), (a->value.list.count==2&&eval(r,e,a->value.list.items[1],&w)?w:jcm_value_number(0)),out);op=a->value.list.items[0]->value.op;switch(op){case JCM_AND:if(!number_arg(r,e,a->value.list.items[1],&n))return 0;if(!n){*out=jcm_value_number(0);return 1;}return number_arg(r,e,a->value.list.items[2],&n)?(*out=jcm_value_number(n!=0),1):0;case JCM_OR:if(!number_arg(r,e,a->value.list.items[1],&n))return 0;if(n){*out=jcm_value_number(1);return 1;}return number_arg(r,e,a->value.list.items[2],&n)?(*out=jcm_value_number(n!=0),1):0;case JCM_NOT:return number_arg(r,e,a->value.list.items[1],&n)?(*out=jcm_value_number(!n),1):0;case JCM_EQ:case JCM_LT:case JCM_LE:case JCM_GT:case JCM_GE:return eval_compare(r,e,a,op,out);case JCM_ADD:case JCM_SUB:case JCM_MUL:case JCM_DIV:case JCM_MOD:return eval_binary(r,e,a,op,out);case JCM_SUM:return eval_sum_product(r,e,a,0,out);case JCM_PRODUCT:return eval_sum_product(r,e,a,1,out);case JCM_INTEGRAL:return eval_integral(r,e,a,out);case JCM_IF:if(a->value.list.count!=4||!number_arg(r,e,a->value.list.items[1],&n))return 0;return eval(r,e,a->value.list.items[n?2:3],out);case JCM_LAMBDA:if(a->value.list.count!=3||a->value.list.items[1]->kind!=JCM_AST_LIST||a->value.list.items[1]->value.list.count!=1||a->value.list.items[1]->value.list.items[0]->kind!=JCM_AST_SYMBOL)return 0;f=malloc(sizeof *f);if(!f)return 0;f->lambda=a;f->env=e;*out=jcm_value_function(f);return 1;case JCM_BIND:if(a->value.list.count!=3)return 0;name=a->value.list.items[0]->kind==JCM_AST_SYMBOL?a->value.list.items[0]:a->value.list.items[1];if(!eval(r,e,a->value.list.items[2],&v)||name->kind!=JCM_AST_SYMBOL||!jcm_env_define(e,name->value.symbol,v))return 0;*out=v;return 1;case JCM_LOAD:if(a->value.list.count!=2||!number_arg(r,e,a->value.list.items[1],&n))return 0;return jcm_memory_load(&r->memory,n,out);case JCM_STORE:if(a->value.list.count!=3||!number_arg(r,e,a->value.list.items[1],&n)||!eval(r,e,a->value.list.items[2],&v)||!jcm_memory_store(&r->memory,n,v))return 0;*out=v;return 1;case JCM_INPUT:if(a->value.list.count!=1||scanf("%ld",&n)!=1)return 0;*out=jcm_value_number(n);return 1;case JCM_OUTPUT:if(a->value.list.count!=2||!eval(r,e,a->value.list.items[1],&v))return 0;if(v.kind==JCM_VALUE_NUMBER)printf("%ld",v.value.number);else if(v.kind==JCM_VALUE_STRING)fputs(v.value.string,stdout);else return 0;*out=v;return 1;}return 0;}
int jcm_eval(struct JCMRuntime *r,struct JCMEnv *e,const struct JCMAst *a,struct JCMValue *v){return eval(r,e,a,v);}
int jcm_eval_program(struct JCMRuntime *r,const struct JCMAst *p,struct JCMValue *v){struct JCMValue x=jcm_value_number(0);int i;if(!r||!p||!v||p->kind!=JCM_AST_PROGRAM)return 0;for(i=0;i<p->value.list.count;i++)if(!eval(r,r->global,p->value.list.items[i],&x))return 0;*v=x;return 1;}
void jcm_value_print(struct JCMValue v){switch(v.kind){case JCM_VALUE_NUMBER:case JCM_VALUE_BOOLEAN:printf("%ld\n",v.value.number);break;case JCM_VALUE_STRING:printf("%s\n",v.value.string);break;case JCM_VALUE_FUNCTION:printf("<function>\n");break;}}
